CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text NOT NULL UNIQUE, password_hash text NOT NULL, email_verified_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE organizations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, personal boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE organization_members (organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, role text NOT NULL CHECK(role IN ('owner','admin','operator','viewer')), PRIMARY KEY (organization_id,user_id));
CREATE INDEX organization_members_user_idx ON organization_members(user_id);
CREATE TABLE sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, refresh_hash text NOT NULL UNIQUE, expires_at timestamptz NOT NULL, revoked_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), last_used_at timestamptz);
CREATE INDEX sessions_user_idx ON sessions(user_id, expires_at);
CREATE TABLE auth_challenges (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, kind text NOT NULL CHECK(kind IN ('verify_email','reset_password')), token_hash text NOT NULL UNIQUE, expires_at timestamptz NOT NULL, consumed_at timestamptz);
CREATE TABLE servers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, name text NOT NULL, hostname text, public_ip inet, private_ip inet, provider text, region text, operating_system text, architecture text, agent_version text, tags text[] NOT NULL DEFAULT '{}', status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','online','offline')), last_seen_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX servers_organization_idx ON servers(organization_id);
CREATE TABLE server_agents (server_id uuid PRIMARY KEY REFERENCES servers(id) ON DELETE CASCADE, credential_hash text, pairing_hash text UNIQUE, pairing_expires_at timestamptz, paired_at timestamptz, revoked_at timestamptz);
CREATE TABLE server_metrics (server_id uuid NOT NULL REFERENCES servers(id) ON DELETE CASCADE, bucket_at timestamptz NOT NULL, sample_count integer NOT NULL DEFAULT 1, cpu_percent numeric(5,2) NOT NULL, memory_percent numeric(5,2) NOT NULL, disk_percent numeric(5,2) NOT NULL, load_1 numeric(10,2), network_rx_bytes bigint, network_tx_bytes bigint, PRIMARY KEY(server_id,bucket_at));
CREATE INDEX server_metrics_time_idx ON server_metrics(bucket_at DESC);
CREATE TABLE audit_logs (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, organization_id uuid REFERENCES organizations(id) ON DELETE SET NULL, actor_id uuid REFERENCES users(id) ON DELETE SET NULL, action text NOT NULL, resource_type text NOT NULL, resource_id text, ip inet, metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX audit_logs_org_time_idx ON audit_logs(organization_id, created_at DESC);
CREATE TABLE services (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), server_id uuid NOT NULL REFERENCES servers(id) ON DELETE CASCADE, name text NOT NULL, state text NOT NULL, UNIQUE(server_id,name));
CREATE TABLE containers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), server_id uuid NOT NULL REFERENCES servers(id) ON DELETE CASCADE, engine_id text NOT NULL, name text NOT NULL, state text NOT NULL, UNIQUE(server_id,engine_id));
CREATE TABLE applications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, server_id uuid REFERENCES servers(id), name text NOT NULL);
CREATE TABLE deployments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), application_id uuid NOT NULL REFERENCES applications(id), commit_sha text, branch text, state text NOT NULL CHECK(state IN ('queued','cloning','building','deploying','health-checking','successful','failed','rolled-back')), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE deployment_events (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, deployment_id uuid NOT NULL REFERENCES deployments(id) ON DELETE CASCADE, state text NOT NULL, message text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE domains (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), application_id uuid NOT NULL REFERENCES applications(id), hostname text NOT NULL UNIQUE, proxy_type text NOT NULL CHECK(proxy_type IN ('caddy','nginx')), certificate_expires_at timestamptz);
CREATE TABLE health_checks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), server_id uuid REFERENCES servers(id), kind text NOT NULL CHECK(kind IN ('http','https','tcp')), target text NOT NULL, interval_seconds integer NOT NULL CHECK(interval_seconds >= 30), timeout_seconds integer NOT NULL CHECK(timeout_seconds > 0), expected_status integer, failure_threshold integer NOT NULL DEFAULT 3);
CREATE TABLE health_check_results (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, health_check_id uuid NOT NULL REFERENCES health_checks(id) ON DELETE CASCADE, checked_at timestamptz NOT NULL DEFAULT now(), success boolean NOT NULL, response_ms integer);
CREATE INDEX health_check_results_time_idx ON health_check_results(health_check_id,checked_at DESC);
CREATE TABLE alerts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), server_id uuid REFERENCES servers(id), kind text NOT NULL, state text NOT NULL CHECK(state IN ('open','acknowledged','resolved')), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE notifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id), alert_id uuid REFERENCES alerts(id), type text NOT NULL, title text NOT NULL, read_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE backup_jobs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), server_id uuid NOT NULL REFERENCES servers(id), kind text NOT NULL, schedule text NOT NULL, retention_count integer NOT NULL CHECK(retention_count > 0));
CREATE TABLE backups (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), job_id uuid NOT NULL REFERENCES backup_jobs(id), status text NOT NULL CHECK(status IN ('pending','running','verifying','successful','failed')), size_bytes bigint, verified_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), CHECK(status <> 'successful' OR verified_at IS NOT NULL));
CREATE TABLE secrets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), name text NOT NULL, ciphertext bytea NOT NULL, nonce bytea NOT NULL, key_version integer NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id,name));
